type Option func(*User)

func WithEmail(e string) Option { return func(u *User) { u.Email = e } }

func testUser(t testing.TB, opts ...Option) User {
    t.Helper()
    u := User{Name: "Ada Lovelace", Email: "ada@example.com", Age: 30}
    for _, opt := range opts { opt(&u) }
    return u
}

u := testUser(t, WithEmail("bad@example.com"))
